package com.copyplayername;

import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import javax.inject.Provider;
import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.menus.MenuManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Copy Player Name",
	description = "Copy player names to clipboard with a simple right-click option.",
	tags = {"copy", "player", "name", "clipboard", "chat"}
)
public class CopyPlayerNamePlugin extends Plugin
{

	private static final String COPY_NAME = "Copy Name";

	@Inject
	private Client client;

	@Inject
	private Provider<MenuManager> menuManager;

	@Inject
	private CopyPlayerNameConfig config;

	@Provides
	CopyPlayerNameConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CopyPlayerNameConfig.class);
	}

	@Override
	protected void startUp()
	{
		updatePlayerMenuItem();
	}

	@Override
	protected void shutDown()
	{
		menuManager.get().removePlayerMenuItem(COPY_NAME);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals("copyPlayerName") && event.getKey().equals("showPlayerButton"))
		{
			updatePlayerMenuItem();
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.showChatButton()
			|| (event.getType() != MenuAction.CC_OP.getId() && event.getType() != MenuAction.CC_OP_LOW_PRIORITY.getId())
			|| !isChatPlayerMenu(event))
		{
			return;
		}

		client.getMenu().createMenuEntry(-2)
			.setOption(COPY_NAME)
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(menuEntry -> copyName(menuEntry.getTarget()));
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getMenuAction() != MenuAction.RUNELITE_PLAYER || !event.getMenuOption().equals(COPY_NAME))
		{
			return;
		}

		Player player = event.getMenuEntry().getPlayer();
		if (player != null)
		{
			copyName(player.getName());
		}
	}

	private void updatePlayerMenuItem()
	{
		menuManager.get().removePlayerMenuItem(COPY_NAME);
		if (config.showPlayerButton())
		{
			menuManager.get().addPlayerMenuItem(COPY_NAME);
		}
	}

	private static boolean isChatPlayerMenu(MenuEntryAdded event)
	{
		int groupId = WidgetUtil.componentToInterface(event.getActionParam1());
		return !event.getTarget().isEmpty()
			&& (groupId == InterfaceID.CHATBOX || groupId == InterfaceID.PM_CHAT)
			&& (event.getOption().equals("Message") || event.getOption().equals("Add ignore"));
	}

	private void copyName(String name)
	{
		String plainName = Text.removeTags(name);
		if (plainName.isEmpty())
		{
			return;
		}

		try
		{
			StringSelection selection = new StringSelection(plainName);
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(selection, selection);
		}
		catch (IllegalStateException exception)
		{
			log.debug("Unable to copy player name because the clipboard is unavailable", exception);
		}
	}
}

package com.copyplayername;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("copyPlayerName")
public interface CopyPlayerNameConfig extends Config
{
	@ConfigItem(
		keyName = "showChatButton",
		name = "Show Chat Button",
		description = "Show the 'Copy Name' button when right-clicking player names in chat.",
		position = 1
	)
	default boolean showChatButton()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPlayerButton",
		name = "Show Player Button",
		description = "Show the 'Copy Name' button when right-clicking player models.",
		position = 1
	)
	default boolean showPlayerButton()
	{
		return true;
	}
}
